// swift-tools-version: 6.0
// ChapterUI: the phone's screen tokens v2 and shared SwiftUI components (design v2, artboard 2k):
// colours, Inter and Times type, metrics, the real Chapter logo, the navigation bar appearance and
// the components every phone screen uses (CaptureUI, FieldKitUI and the app's package screens).
//
// Targets
// - ChapterUI: SwiftUI + UIKit. Bundles Inter Regular and SemiBold (Fonts/, generated by
//   tools/brand/generate_plan_brand.py) and registers them at runtime (`ChapterFonts.register()`;
//   never `UIAppFonts`, which cannot see a package's bundle).
// - ChapterUISnapshotTesting: the one snapshot harness of every phone snapshot test (a UIWindow of
//   402 x 874 pt at scale 3, `drawHierarchy`, > 8/255 on more than 0.5 % of pixels fails).
//
// Outside the package: SnapshotHost/ (an empty app) and HostedTests/ are the app-hosted snapshot
// tests of the boards with system chrome, built from ios/project.yml (scheme ChapterUISnapshots),
// because `drawHierarchy` needs a UIApplication that Swift package tests do not have.
//
// Every source is wrapped in `#if canImport(SwiftUI) && os(iOS)` (the harness also needs XCTest),
// so both targets compile to empty modules on Linux and macOS and dependants still build there.
// There is deliberately no `.apple-only` marker at the package root: scripts/swift-test.sh then
// builds the package on Linux, which checks those guards. The macOS runner (ios.yml, job
// ChapterUI) builds it for iOS and runs the snapshot tests on the simulator.
import PackageDescription

let package = Package(
  name: "ChapterUI",
  platforms: [
    .iOS(.v17),
    .macOS(.v14),
  ],
  products: [
    .library(name: "ChapterUI", targets: ["ChapterUI"]),
    .library(name: "ChapterUISnapshotTesting", targets: ["ChapterUISnapshotTesting"]),
  ],
  targets: [
    .target(
      name: "ChapterUI",
      exclude: [".apple-only"],
      resources: [.process("Fonts")]
    ),
    .target(
      name: "ChapterUISnapshotTesting",
      dependencies: ["ChapterUI"],
      exclude: [".apple-only"]
    ),
    .testTarget(
      name: "ChapterUITests",
      dependencies: ["ChapterUI", "ChapterUISnapshotTesting"],
      // Reference PNGs; the tests read them from the source tree (#filePath).
      exclude: ["__Snapshots__"]
    ),
  ]
)
